"use client";

import { Easing, interpolate } from "remotion";
import { useSceneConfig, useSceneFrame } from "@/lib/remocn/frame-rate";
import { type Timing, useTimeline } from "@/lib/remocn/timeline";
import {
  type LineByLineSlideElementId,
  lineByLineSlideTimeline,
} from "./timeline";

export interface LineByLineSlideProps {
  text: string;
  distance?: number;
  fontSize?: number;
  color?: string;
  fontWeight?: number;
  speed?: number;
  className?: string;
  /**
   * Moves, trims or stretches single lines and their exits, by the ids in
   * `./timeline`. Frames on the scene timeline, after `speed`.
   */
  timing?: Timing<LineByLineSlideElementId>;
}

export function LineByLineSlide(props: LineByLineSlideProps) {
  const {
    text,
    distance = 48,
    fontSize = 72,
    color = "#171717",
    fontWeight = 600,
    speed = 1,
    className,
    timing,
  } = props;
  const frame = useSceneFrame() * speed;
  const { durationInFrames } = useSceneConfig();
  // The exit is timed against the composition length without `speed`.
  const tl = useTimeline(
    lineByLineSlideTimeline,
    props,
    durationInFrames,
    timing,
  );

  const lines = text.split("\n");

  const enterEasing = Easing.bezier(0.22, 1, 0.36, 1);
  const exitEasing = Easing.bezier(0.64, 0, 0.78, 0);

  return (
    <div
      style={{
        position: "absolute",
        inset: 0,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        background: "transparent",
      }}
    >
      <span
        className={className}
        style={{
          fontSize,
          fontWeight,
          color,
          letterSpacing: "-0.03em",
          lineHeight: 1.1,
          textAlign: "left",
          fontFamily:
            "var(--font-geist-sans), -apple-system, BlinkMacSystemFont, sans-serif",
        }}
      >
        {lines.map((line, i) => {
          const enter = tl.get(`line:${i}`);
          const exit = tl.get(`exit:${i}`);
          const enterLocal = frame - enter.start;
          const exitLocal = frame - exit.start;
          const enterDur = enter.length;
          const enterTravel = enter.beat("travel");
          const exitDur = exit.length;
          const exitTravelFrom = exit.beat("travelFrom");

          const enterP = interpolate(enterLocal, [0, enterDur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: enterEasing,
          });

          const exitP = interpolate(exitLocal, [0, exitDur], [0, 1], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
            easing: exitEasing,
          });

          const opacity = enterP * (1 - exitP);

          const xEnter = interpolate(
            enterLocal,
            [0, enterTravel],
            [-distance, 0],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: enterEasing,
            },
          );

          const xExit = interpolate(
            exitLocal,
            [exitTravelFrom, exitDur],
            [0, distance],
            {
              extrapolateLeft: "clamp",
              extrapolateRight: "clamp",
              easing: exitEasing,
            },
          );

          const x = xEnter + xExit;

          return (
            <span
              key={i}
              style={{
                display: "block",
                transformOrigin: "0% 50%",
                opacity,
                translate: `${x}px`,
              }}
            >
              {line}
            </span>
          );
        })}
      </span>
    </div>
  );
}

import { defineTimeline, type TimelineElement } from "@/lib/remocn/timeline";

// When each line slides in and when it slides out. Frames on the 30 fps
// scene timeline, after `speed`. The ids are public: a saved `timing` prop
// refers to them.

export type LineByLineSlideElementId = `line:${number}` | `exit:${number}`;

export interface LineByLineSlideTimingProps {
  text: string;
}

/** A line fades in over `ENTER`, sliding for the first `ENTER_TRAVEL`. */
const ENTER = 27;
const ENTER_TRAVEL = 14;
const ENTER_STAGGER = 4;
/** A line fades out over `EXIT`, sliding from `EXIT_TRAVEL_FROM` on. */
const EXIT = 18;
const EXIT_TRAVEL_FROM = 8;
const EXIT_STAGGER = 2;

// The exit is timed to end with the scene. `length` here is the composition
// length in scene frames without `speed`, as the component has always read
// it, so a faster scene still leaves at the end of the composition's frames.
export const lineByLineSlideTimeline = defineTimeline<
  LineByLineSlideElementId,
  LineByLineSlideTimingProps
>(({ text }, { length }) => {
  const lines = text.split("\n");
  const enterEnd = ENTER + (lines.length - 1) * ENTER_STAGGER;
  const exitStart = Math.max(
    enterEnd,
    length - EXIT - (lines.length - 1) * EXIT_STAGGER,
  );
  return [
    ...lines.map(
      (line, i): TimelineElement<LineByLineSlideElementId> => ({
        id: `line:${i}`,
        lane: "In",
        label: line,
        start: i * ENTER_STAGGER,
        length: ENTER,
        follows: i > 0 ? `line:${i - 1}` : undefined,
        beats: { travel: ENTER_TRAVEL },
      }),
    ),
    ...lines.map(
      (line, i): TimelineElement<LineByLineSlideElementId> => ({
        id: `exit:${i}`,
        lane: "Out",
        label: line,
        start: exitStart + i * EXIT_STAGGER,
        length: EXIT,
        follows: i > 0 ? `exit:${i - 1}` : `line:${lines.length - 1}`,
        beats: { travelFrom: EXIT_TRAVEL_FROM },
      }),
    ),
  ];
});
